-- B31P 第四批 Q5-B：表单字段引用的枚举（enumInfo 形如 <枚举 ID>_false_<n>_[字段]，取下划线前的数字为 CTP_ENUM.ID；若不对应则下面无行）及其枚举项。只读；one_evidence_ro（ADR-0037 第 7 项）。
SET LOCK_TIMEOUT 1000;
SELECT e.ID AS enum_id, COUNT_BIG(*) AS item_count FROM a8_db.dbo.CTP_ENUM AS e JOIN a8_db.dbo.CTP_ENUM_ITEM AS i ON i.REF_ENUMID = e.ID
 WHERE DB_NAME() = N'a8_db' AND e.ID IN (-7391496778928405449, -7342233378416668993, -4385749188867961438, -3494224496022304687, -3472409557441036019, -2667337719256758192, -2454450906200063743, 1534654868854620891, 1716024204443730308, 2326016881727851812, 3783704123441168666, 5117652334517701119, 6039499715297166506, 7089441405752199241, 8169289548988237789, 8915756690597432062) GROUP BY e.ID ORDER BY e.ID;
SELECT TOP (500) e.ID AS enum_id, e.DESCRIPTION AS enum_description, e.ENUMNAME AS enum_name, i.SORTNUMBER AS item_order, i.SHOWVALUE AS item_label, i.ENUMVALUE AS item_value, i.STATE AS item_state
  FROM a8_db.dbo.CTP_ENUM AS e JOIN a8_db.dbo.CTP_ENUM_ITEM AS i ON i.REF_ENUMID = e.ID
 WHERE DB_NAME() = N'a8_db' AND e.ID IN (-7391496778928405449, -7342233378416668993, -4385749188867961438, -3494224496022304687, -3472409557441036019, -2667337719256758192, -2454450906200063743, 1534654868854620891, 1716024204443730308, 2326016881727851812, 3783704123441168666, 5117652334517701119, 6039499715297166506, 7089441405752199241, 8169289548988237789, 8915756690597432062)
 ORDER BY e.ID, i.SORTNUMBER;
